describe('messageProjectionToValue', () => {
  const value = {
    uid: 'value-uid',
    target: 'value-target',
    tenant: { $ref: 'ref-tenant' },
    urgent: 'value-urgent',
    content: 'value-content',
    retries: 'value-retries',
    createdAt: 'value-createdAt',
    sendAt: 'value-sendAt',
    lockAt: 'value-lockAt',
    version: 'value-version',
  } as any;

  it('returns null without projection', () => {
    expect(messageProjectionToValue(null)).toBeNull();
    expect(messageProjectionToValue(undefined)).toBeNull();
  });

  it('keeps a plain value', () => {
    expect(messageProjectionToValue(value)).toEqual(value);
  });

  it('reduces the projected references to their key', () => {
    const projection = {
      uid: 'value-uid',
      target: 'value-target',
      tenant: () => ({ uid: 'ref-tenant' }),
      urgent: 'value-urgent',
      content: 'value-content',
      retries: 'value-retries',
      createdAt: 'value-createdAt',
      sendAt: 'value-sendAt',
      lockAt: 'value-lockAt',
      version: 'value-version',
    } as any;
    expect(messageProjectionToValue(projection)).toEqual(value);
  });
});
